def _source_node_hashes(source: str) -> dict[str, str]:
    tree = ast.parse(source)
    hashes = {}
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.ClassDef)) and node.name in LEGACY_NODE_SHA256:
            segment = ast.get_source_segment(source, node)
            hashes[node.name] = hashlib.sha256(segment.encode("utf-8")).hexdigest()
    return hashes


def bind_legacy_writer(runner):
    """Compile the exact old writer against pinned, unchanged serializer helpers."""
    if _source_node_hashes(_LEGACY_SOURCE) != LEGACY_NODE_SHA256:
        raise AssertionError("pinned v1 writer fixture source changed")

    runner_source = open(runner.__file__, "r", encoding="utf-8").read()
    runner_tree = ast.parse(runner_source)
    current_helpers = {
        node.name: node
        for node in runner_tree.body
        if isinstance(node, (ast.FunctionDef, ast.ClassDef)) and node.name in LEGACY_HELPER_SHA256
    }
    for name, expected in LEGACY_HELPER_SHA256.items():
        node = current_helpers.get(name)
        if node is None:
            raise AssertionError("pinned v1 helper missing: " + name)
        segment = ast.get_source_segment(runner_source, node)
        if hashlib.sha256(segment.encode("utf-8")).hexdigest() != expected:
            raise AssertionError("pinned v1 helper changed: " + name)

    namespace = dict(runner.__dict__)
    namespace["DECISION_TAPE_SCHEMA"] = LEGACY_DECISION_TAPE_SCHEMA
    exec(compile(_LEGACY_SOURCE, "<pinned-alpha003-v1-writer>", "exec"), namespace)
    return namespace["DecisionTapeWriter"]
